-- Německé názvy a popisy surovin pro katalog na webu (/de/suroviny).
-- Přeloženo z českých řádků food_translations; appka sama je nevyrábí,
-- nová surovina v appce spadne na webu na angličtinu (viz src/lib/foods.ts).
-- Idempotentní: řádek se vloží jen tam, kde německý překlad ještě není.

insert into public.food_translations (food_id, locale, name, description)
select v.food_id::uuid, 'de', v.name, v.description
from (values
  ('29309265-98fe-48df-ab2b-cf366109d04a', $t$Sardellen (Anchovis)$t$, $t$Sardellen (Anchovis) – kleine fette Seefische, reich an Omega-3 und Kalzium (werden ganz gefressen). Frisch/gefroren verwenden, nicht gesalzen. Fetter Seefisch, wertvolle Quelle für Omega-3 und Vitamin D. 1–2× pro Woche einplanen.$t$),
  ('a0000006-0000-0000-0000-000000000003', $t$Banane$t$, $t$Banane – süßes Obst, reich an Kalium. Nur sehr kleine Mengen. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('c689b537-46e6-45e2-9afc-a310893e6d7c', $t$Süßkartoffeln$t$, $t$Süßkartoffeln – Quelle für Ballaststoffe und Beta-Carotin. Nur gegart füttern. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('6051e9b5-863b-4631-8ad4-3e5dda636b4c', $t$Naturjoghurt$t$, $t$Naturjoghurt – Probiotika und Kalzium. Kleine Mengen. Milchprodukt als Ergänzung – nur in kleinen Mengen, manche Hunde vertragen Laktose schlecht. Quelle für Protein und Kalzium.$t$),
  ('a0000006-0000-0000-0000-000000000002', $t$Heidelbeeren$t$, $t$Heidelbeeren – Antioxidantien, idealer kleiner Snack. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('a0000005-0000-0000-0000-000000000002', $t$Brokkoli$t$, $t$Brokkoli – Kreuzblütler mit Vitamin C. Nur kleine Mengen. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('fb1b6b73-6cf9-4060-85bc-f747d54d384a', $t$Staudensellerie$t$, $t$Staudensellerie – kalorienarmes, saftiges Gemüse mit Ballaststoffen. Fein schneiden oder pürieren (faserige Stangen). Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('76ebab08-3cc8-4db3-af20-febdb22d4b50', $t$Schwarze Johannisbeeren$t$, $t$Schwarze Johannisbeeren – dunkle Beeren mit außergewöhnlich viel Vitamin C. Ribes, keine Weintrauben – in kleinen Mengen sicher. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('6f014bae-e624-452e-a44e-c19e35e86d05', $t$Rote Johannisbeeren$t$, $t$Rote Johannisbeeren – säuerliche Beeren, reich an Vitamin C und Ballaststoffen. Johannisbeeren (Ribes) sind keine Weintrauben, für Hunde in kleinen Mengen sicher. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('a0000005-0000-0000-0000-000000000003', $t$Zucchini$t$, $t$Zucchini – leichtes, gut verdauliches Gemüse mit wenig Kalorien. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('0c85323f-f4b7-420d-aeee-f5075540d621', $t$Damwildfleisch$t$, $t$Damwildfleisch – mageres Wildfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus. Stammt das Wild nicht aus einer geprüften Quelle (z. B. aus dem Supermarkt), lieber durchgaren.$t$),
  ('702a5427-731f-4730-8f64-7efd6289ac10', $t$Wildschwein$t$, $t$Wildschwein – dunkles Wildfleisch. Einfrieren wegen Aujeszky-Krankheit und Trichinen. Basis der Ration – macht 50–70 % des Fleischanteils aus. Stammt das Wild nicht aus einer geprüften Quelle (z. B. aus dem Supermarkt), lieber durchgaren.$t$),
  ('16d2ff5e-eadc-4bfd-ad6b-081e7b14cc9a', $t$Kürbis$t$, $t$Kürbis – sanfte Ballaststoffe, unterstützt die Verdauung. Gekocht füttern. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('19aea7c3-4afb-4e44-9713-577739581ec8', $t$Rinderpansen$t$, $t$Rinderpansen – grüner, ungewaschener Pansen unterstützt Verdauung und Mikrobiom. Magen (Pansen) – grün und ungewaschen ist er großartig für Verdauung und Mikrobiom. Zählt zum Muskelfleisch.$t$),
  ('a0000004-0000-0000-0000-000000000002', $t$Rinderleber$t$, $t$Rinderleber – die klassische, häufigste Leberquelle beim BARFen. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('e1b1a750-4fbf-4aae-9268-48e42b6799b6', $t$Rinderzunge$t$, $t$Rinderzunge – fettreicheres Muskelfleisch, zählt zum Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('a0000003-0000-0000-0000-000000000003', $t$Rindernieren$t$, $t$Rindernieren – sekretorisches Organ, reich an Selen und B-Vitaminen. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('d5b54d70-b04c-4e41-b3f8-e6cf43a8b0a8', $t$Rinderbäckchen$t$, $t$Rinderbäckchen – Arbeitsmuskel, mager und saftig. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('dfe72b7d-72a0-46b2-a91e-9363997b2a49', $t$Rindermarkknochen$t$, $t$Rindermarkknochen – sehr harter tragender Knochen, nur zum Kauen. Härterer tragender Knochen – eher zum Kauen als zum Verfüttern. IMMER roh, auf Zahnabnutzung achten.$t$),
  ('1395dd80-e114-4772-af5b-27900c91b465', $t$Rinderhirn$t$, $t$Rinderhirn – Quelle gesunder Fette und DHA. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('f3249739-7cd5-4a86-a39d-f724e019a0e6', $t$Ochsenschwanz$t$, $t$Ochsenschwanz – fleischiger Knochen mit Knorpel, Kollagenquelle. Härterer tragender Knochen – eher zum Kauen als zum Verfüttern. IMMER roh, auf Zahnabnutzung achten.$t$),
  ('a0000003-0000-0000-0000-000000000004', $t$Rinderlunge$t$, $t$Rinderlunge – leichtes, fettarmes Organ. Als Ergänzung des Fleischanteils füttern, getrocknet auch ein beliebter Snack.$t$),
  ('aaf196f4-c2ea-4251-bf7a-a286ed463234', $t$Rinderluftröhre$t$, $t$Rinderluftröhre – Knorpel mit Glucosamin, ausgezeichneter Kausnack. Knorpelteil – natürliche Quelle von Glucosamin und Chondroitin für die Gelenke. Beliebter Kausnack.$t$),
  ('9acb18fb-345e-4b90-9dfa-1572ee0d4c80', $t$Rindermilz$t$, $t$Rindermilz – sekretorisches Organ, sehr reich an Eisen. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('3f9c2160-688e-4799-8c46-e968d7098af8', $t$Rinderbauchspeicheldrüse$t$, $t$Rinderbauchspeicheldrüse – sekretorisches Organ, natürliche Enzyme (geeignet bei EPI). Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('a0000003-0000-0000-0000-000000000002', $t$Rinderherz$t$, $t$Rinderherz – hervorragende Taurinquelle, preiswert. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('a0000001-0000-0000-0000-000000000002', $t$Rindermuskelfleisch$t$, $t$Rindermuskelfleisch – das grundlegende magere Fleisch der BARF-Ration. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('56778459-2e46-48e7-bc0b-9c66363f028a', $t$Rindereuter$t$, $t$Rindereuter – fettes ergänzendes Muskelfleisch. Zählt zum Muskelfleisch, nicht zu den Innereien – hat weder Vitamin A, Kupfer noch Selen wie Leber oder Nieren. Wenig Protein und viel Fett, also nur zur Abwechslung – Rindfleisch ersetzt es nicht.$t$),
  ('45ce601b-9401-40c7-bbce-cd0e0be3e84e', $t$Birne$t$, $t$Birne – saftiges Obst mit Ballaststoffen. Ohne Kerngehäuse. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('adfbf92d-ab6a-4667-8bbb-c4f11c9456d1', $t$Gänseleber$t$, $t$Gänseleber – fett und reichhaltig, nur in kleinen Mengen. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('50cd76c8-593c-4209-adf0-288ddacdc443', $t$Gänsehälse$t$, $t$Gänsehälse – fettreicherer großer essbarer Knochen. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('1ac34fa5-d58e-4174-8e68-4d60bd04719a', $t$Gänsefleisch$t$, $t$Gänsefleisch – fettreicheres Geflügel, kräftiger Geschmack. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('a0000006-0000-0000-0000-000000000001', $t$Apfel$t$, $t$Apfel – Quelle für Ballaststoffe und Vitamin C. Kerngehäuse entfernen (die Kerne enthalten Cyanid). Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('2bf512d2-fe48-40b4-a185-3148bbf4b741', $t$Erdbeeren$t$, $t$Erdbeeren – Vitamin C und Ballaststoffe, als Snack. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('7164342c-b939-45eb-b9aa-871d02c062e8', $t$Lammleber$t$, $t$Lammleber – reich an Kupfer und Vitamin A. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('d35ddd87-a7b9-43cf-9455-3ab48b9c9ee6', $t$Lammzunge$t$, $t$Lammzunge – fettreicheres Muskelfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('ee19cd47-c739-4e64-a446-b33795e3d842', $t$Lammnieren$t$, $t$Lammnieren – kleinere Nieren, zarter. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('a0000001-0000-0000-0000-000000000004', $t$Lammfleisch$t$, $t$Lammfleisch – fettreicheres rotes Fleisch mit kräftigem Geschmack. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('07e8641d-d73b-44d1-b437-057fbde6e71b', $t$Lammlunge$t$, $t$Lammlunge – leichtes Organ, beliebt als getrockneter Snack. Leichtes, fettarmes Organ. Als Ergänzung des Fleischanteils füttern, getrocknet auch ein beliebter Snack.$t$),
  ('f925dca9-49b2-4c90-a1a9-ed4fb158c7bd', $t$Lammherz$t$, $t$Lammherz – kleineres Herz, ideal für mittelgroße Hunde. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('3c87d0ca-fee4-45ac-853a-bc90a308dcef', $t$Lammrippen$t$, $t$Lammrippen – essbarer Knochen mit einer Schicht Fleisch und Fett. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('fc9b60eb-dc25-43c2-bae7-6e5502792888', $t$Hirschleber$t$, $t$Hirschleber – Wildleber, reich an Nährstoffen. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('ed329b3b-fb4e-41cb-b303-1da314174fc4', $t$Entenleber$t$, $t$Entenleber – fettreichere Geflügelleber. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('c74f3c78-af49-48a4-9eee-590b7eacc587', $t$Entenflügel$t$, $t$Entenflügel – fleischiger essbarer Knochen. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000002-0000-0000-0000-000000000003', $t$Entenhälse$t$, $t$Entenhälse – größerer essbarer Knochen für mittelgroße und große Hunde. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000001-0000-0000-0000-000000000005', $t$Entenbrust$t$, $t$Entenbrust – magereres dunkles Geflügelfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('a4f6cd41-cea7-4fa5-adfc-3b11c0b64dc0', $t$Entenkarkassen$t$, $t$Entenkarkassen – fettreicheres Gerippe mit Knorpel. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('2e3cc505-ceb6-4c91-87c7-efbaba617d87', $t$Entenherzen$t$, $t$Entenherzen – kleines Muskelorgan mit Taurin. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('53361084-adb1-43de-8ac2-ac73025ccd1c', $t$Entenmägen$t$, $t$Entenmägen – muskulös und schmackhaft. Muskelmagen, zählt zum Muskelfleisch. Von Natur aus proteinreich.$t$),
  ('8a817089-1223-4042-8ea3-e01e0e265b78', $t$Pferdeleber$t$, $t$Pferdeleber – mager und reich an Eisen. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('e36871a2-7e20-4c68-90d9-0df96ec31118', $t$Pferdefleisch$t$, $t$Pferdefleisch – mager, hypoallergen, geeignet bei Allergien. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('f81d67a3-a49e-49f3-af72-27ee577c3ed0', $t$Pferdeherz$t$, $t$Pferdeherz – mageres Muskelorgan. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('1f48fd0f-78a3-4091-8c7b-49e39bc39c3c', $t$Ziegenfleisch$t$, $t$Ziegenfleisch – mageres rotes Fleisch, wenig allergen. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('0236d8aa-8504-4618-94ea-a37b83a6a572', $t$Kaninchenleber$t$, $t$Kaninchenleber – magere Leber eines mageren Fleischtiers. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('1ef4deb1-21c7-44a0-9215-8d6350bf5d6b', $t$Kaninchenfleisch$t$, $t$Kaninchenfleisch – mager und leicht verdaulich, hypoallergen. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('53081f21-372e-44e9-87bb-d933f5f475e1', $t$Kaninchen ganz (mit Knochen)$t$, $t$Ganzes Kaninchen mit Knochen – komplettes Beutetier: Muskelfleisch, essbare Knochen und Innereien zusammen. Die App rechnet es grob auf 60 % Muskelfleisch, 30 % Knochen und 10 % Innereien um. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('dc010526-9f58-49cb-8ff1-adb082496379', $t$Wachtel (ganz)$t$, $t$Ganze Wachtel – komplettes kleines Beutetier samt Knochen und Organen. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('20e99202-683d-4dce-97ce-7e29b616f3e1', $t$Putenleber$t$, $t$Putenleber – Leberquelle vom Geflügel. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('68f7535a-d943-4647-92b2-ae4116ca009f', $t$Putenflügel$t$, $t$Putenflügel – fleischiger essbarer Knochen für größere Hunde. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('c4e9cc16-dd6a-4fef-b83e-2bcf2a6cf127', $t$Putenhälse$t$, $t$Putenhälse – großer essbarer Knochen für große Hunde. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000001-0000-0000-0000-000000000003', $t$Putenbrust$t$, $t$Putenbrust – sehr mageres weißes Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('c416d378-17da-493a-a961-4346c65ca704', $t$Putenherz$t$, $t$Putenherz – Muskelorgan, reich an Taurin. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('45c82f5d-99ad-4f15-b714-2ba229bf308d', $t$Putenkeule$t$, $t$Putenkeule – dunkleres, etwas fettreicheres Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('8c2ad4ff-590b-49d4-ad24-00c4ddf6425c', $t$Putenmägen$t$, $t$Putenmägen – muskulöses Organ, zählt zum Muskelfleisch. Muskelmagen, zählt zum Muskelfleisch. Von Natur aus proteinreich.$t$),
  ('a0000002-0000-0000-0000-000000000002', $t$Hühnerrücken$t$, $t$Hühnerrücken mit Knorpel und Fleischresten. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000004-0000-0000-0000-000000000001', $t$Hühnerleber$t$, $t$Hühnerleber – weich und leicht erhältlich, geeignet für kleine Hunde. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('6fa17f82-6bfe-4071-b9ff-eaf134ded315', $t$Hühnerflügel$t$, $t$Hühnerflügel – gut verdaulicher essbarer Knochen. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000002-0000-0000-0000-000000000001', $t$Hühnerhälse$t$, $t$Weiche Hühnerhälse, idealer essbarer Knochen für kleine und mittelgroße Hunde. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('e7d8fcb4-ae47-46c1-89ec-f4324a565e4c', $t$Hühnerfüße$t$, $t$Hühnerfüße – natürliche Glucosaminquelle, beliebter Snack. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000001-0000-0000-0000-000000000001', $t$Hähnchenbrust$t$, $t$Hähnchenbrust – mageres weißes Fleisch, Basis für empfindliche Hunde. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('8086894d-8fb1-4590-bcf2-a88b9cede648', $t$Hühnerkarkassen$t$, $t$Hühnerkarkassen (Gerippe) nach dem Auslösen, mit Knorpel und Fleischresten. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('a0000003-0000-0000-0000-000000000001', $t$Hühnerherzen$t$, $t$Hühnerherzen – kleine Herzen, beliebte Taurinquelle. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('a4b3be39-3cc1-4583-8cd7-7610b627ef70', $t$Hähnchenkeule$t$, $t$Hähnchenkeule – dunkleres, saftiges Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('a824dddb-fd60-4bb3-870c-c2f9501de3ad', $t$Hühnermägen$t$, $t$Hühnermägen – muskulös, zählen zum Muskelfleisch. Muskelmagen, zählt zum Muskelfleisch. Von Natur aus proteinreich.$t$),
  ('7f31950d-8120-4e40-a229-5937b1731d79', $t$Blumenkohl$t$, $t$Blumenkohl – Kreuzblütler mit Vitamin C und Folat. Am besten leicht dünsten. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('b6e5ab5e-544b-4e68-9490-0d1c1c79bee5', $t$Lachs$t$, $t$Lachs – fetter Fisch, reich an Omega-3. Mindestens 3 Wochen gefroren wegen Parasiten. Fetter Seefisch, wertvolle Quelle für Omega-3 und Vitamin D. 1–2× pro Woche einplanen.$t$),
  ('a0000007-0000-0000-0000-000000000001', $t$Lachsöl$t$, $t$Lachsöl – flüssige Omega-3-Quelle für Fell und Gelenke. Ergänzung mit Omega-3-Fettsäuren für Fell und Gelenke. Einige Tropfen bis ml täglich je nach Größe des Hundes.$t$),
  ('0ebe106b-b2c4-4273-937a-3f34bdd94f3b', $t$Makrele$t$, $t$Makrele – fetter Seefisch mit Omega-3. Fetter Seefisch, wertvolle Quelle für Omega-3 und Vitamin D. 1–2× pro Woche einplanen.$t$),
  ('0943f697-a6db-4de0-baf6-62df039a0328', $t$Himbeeren$t$, $t$Himbeeren – Beeren, reich an Ballaststoffen und Vitamin C. Nur kleine Mengen (enthalten Spuren von Xylit). Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('4d946245-2f63-4a2b-876b-53c526b7384b', $t$Gemahlene Eierschale$t$, $t$Gemahlene Eierschale – reines Kalzium für Rationen ohne Knochen. Kalziumergänzung für knochenfreie Rationen. Ca. 1 g (½ Teelöffel) auf 500 g Fleisch.$t$),
  ('5d14b3ac-b118-4cb2-8a3a-0625ee499265', $t$Seealgen$t$, $t$Seealgen – natürliche Jodquelle. Nur eine Prise. Natürliche Jodquelle für die Schilddrüse. Nur eine Prise – Jod ist schnell überdosiert.$t$),
  ('a0000005-0000-0000-0000-000000000001', $t$Karotte$t$, $t$Karotte – Beta-Carotin und Ballaststoffe, auch roh zum Knabbern beliebt. Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('1dc17ceb-c3cb-4328-af14-51131bc06525', $t$Brombeeren$t$, $t$Brombeeren – dunkle Beeren mit Antioxidantien und Ballaststoffen. Idealer kleiner Snack. Obst nur als gelegentlicher Snack in kleinen Mengen wegen des Zuckergehalts.$t$),
  ('b2f1e6a4-7c3d-4b8e-9a12-5f7c9d0e1a23', $t$Lauch$t$, $t$Lauch – Gemüse aus der Gattung Allium. ACHTUNG: Lauch ist für Hunde giftig (wie Zwiebeln und Knoblauch) – er schädigt die roten Blutkörperchen und kann eine hämolytische Anämie auslösen. Nicht zum Verfüttern empfohlen, auch nicht gegart.$t$),
  ('c815843e-9614-4cb4-bd19-df93b3f0726d', $t$Nori-Alge$t$, $t$Nori-Alge – Meeresalge mit Jod und Vitamin A, milder als Kelp. Nur kleine Mengen füttern. Natürliche Jodquelle für die Schilddrüse. Nur kleine Mengen – Jod ist schnell überdosiert.$t$),
  ('b1668561-d079-4ee0-a6b7-df9ccf3286dd', $t$Sardinen$t$, $t$Sardinen – kleine Seefische, ganz mit Gräten. Fetter Seefisch, wertvolle Quelle für Omega-3 und Vitamin D. 1–2× pro Woche einplanen.$t$),
  ('d3c9da3b-e70e-42f7-b815-f019d1d97461', $t$Hering$t$, $t$Hering – fetter Seefisch, Quelle für Omega-3 und Vitamin D. Fetter Seefisch, wertvolle Quelle für Omega-3 und Vitamin D. 1–2× pro Woche einplanen.$t$),
  ('a0000005-0000-0000-0000-000000000004', $t$Spinat$t$, $t$Spinat – Blattgemüse, reich an Eisen. Sparsam (Oxalate). Gemüse – ca. 10 % der Ration. Für bessere Verdaulichkeit pürieren oder leicht dünsten.$t$),
  ('8c40218d-0b9e-49c5-b376-34b3dd3e58bf', $t$Rehfleisch$t$, $t$Rehfleisch – zartes, mageres Wildfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus. Stammt das Wild nicht aus einer geprüften Quelle (z. B. aus dem Supermarkt), lieber durchgaren.$t$),
  ('4258ea8a-cbdb-4349-9b8b-c5714717f8f0', $t$Kalbsleber$t$, $t$Kalbsleber – zarter und leichter als Rinderleber. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('f1085f36-49e8-4bf6-93e6-206687616f05', $t$Kalbsmuskelfleisch$t$, $t$Kalbsmuskelfleisch – zartes, mageres Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('17da90b5-de38-41bd-bbe7-e0a4efb2ec67', $t$Quark$t$, $t$Quark – leichtes Protein und Kalzium. Milchprodukt als Ergänzung – nur in kleinen Mengen, manche Hunde vertragen Laktose schlecht. Quelle für Protein und Kalzium.$t$),
  ('a0000007-0000-0000-0000-000000000002', $t$Ei$t$, $t$Ei – vollständiges Protein; mit Schale auch Kalziumquelle. Ganzes Ei samt Schale – vollständiges Protein und Kalzium. 2–3× pro Woche je nach Größe des Hundes.$t$),
  ('6dff6fc2-dfdd-40cb-9de2-4ac3864885c3', $t$Schweinezwerchfell$t$, $t$Schweinezwerchfell – dünner Zwerchfellmuskel, schmackhaftes Muskelfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('bb8a8f3d-c79d-4ee3-a03b-40943c8e46bb', $t$Schweinekopf$t$, $t$Schweinekopf – Fleisch, Knorpel und Knochen zusammen. Härterer tragender Knochen – eher zum Kauen als zum Verfüttern. IMMER roh, auf Zahnabnutzung achten.$t$),
  ('5cfdf04b-cfba-4cd7-b52e-0dcb6a3844f1', $t$Schweineleber$t$, $t$Schweineleber – gut erhältliche Leberquelle, kräftiger Geschmack. Das wichtigste Organ beim BARFen, extrem reich an Vitamin A, Kupfer und Eisen. Max. 5 % der Ration, sonst droht eine Vitamin-A-Überdosierung.$t$),
  ('af918a13-86cd-4a50-bac8-88b550b4a5a9', $t$Schweinenacken$t$, $t$Schweinenacken – saftigeres, stärker durchwachsenes Stück. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('835bf3b4-0ed7-41f5-a780-0acaef4c3590', $t$Schweinekeule$t$, $t$Schweinekeule – magereres Hinterteil. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('59676165-74e0-4e97-993e-2ce4aa470717', $t$Schweinebäckchen$t$, $t$Schweinebäckchen – saftiger Arbeitsmuskel. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('80f5f491-4091-4b6f-8a93-b30db86cc90a', $t$Schweinemarkknochen$t$, $t$Schweinemarkknochen – harter tragender Knochen, zum Kauen. Härterer tragender Knochen – eher zum Kauen als zum Verfüttern. IMMER roh, auf Zahnabnutzung achten.$t$),
  ('754de29a-cd26-406f-86cd-2c5a82d8ea5d', $t$Schweinefilet$t$, $t$Schweinefilet – das magerste Stück vom Schwein. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('0e056f3b-1cb6-4453-bf8d-1e6029246a46', $t$Schweinerücken (Kotelett)$t$, $t$Schweinerücken (Kotelett) – mageres Rückenfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('c6d2374c-71f7-4f34-a816-f259c96e7448', $t$Schweineschulter$t$, $t$Schweineschulter – mittelfettes Stück. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('1588c11d-3a4d-4ee7-bdb8-13999488b15c', $t$Schweinemilz$t$, $t$Schweinemilz – Organ, reich an Eisen. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('381853bc-32bc-4e3c-842c-f588fd652fd7', $t$Schweinebauchspeicheldrüse$t$, $t$Schweinebauchspeicheldrüse – Quelle von Verdauungsenzymen. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('d5b2b7e3-34e8-4846-812b-da1ea3131e01', $t$Schweinemuskelfleisch$t$, $t$Schweinemuskelfleisch – allgemeines Schweinefleisch. Immer gut durchgefroren (Aujeszky). Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('cc786e81-634e-4aba-acf1-de134cd83850', $t$Schweinerippen$t$, $t$Schweinerippen – fleischiger essbarer Knochen. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('4224fc51-d21a-4c08-ad09-2e20d29f6bec', $t$Schweinshaxe$t$, $t$Schweinshaxe – härterer tragender Knochen mit Fleisch. Härterer tragender Knochen – eher zum Kauen als zum Verfüttern. IMMER roh, auf Zahnabnutzung achten.$t$),
  ('876caa4e-47a0-4ac0-b524-2f5d72aacb97', $t$Schweinenieren$t$, $t$Schweinenieren – gut erhältliches sekretorisches Organ. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('01ffd839-64be-4c08-b7e6-05e49bbc9961', $t$Schweinefüße$t$, $t$Schweinefüße – Haut, Knorpel und Knochen, Kollagenquelle. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('79930f0f-64d7-4f43-a080-8b0f7e2dbd8f', $t$Schweinelunge$t$, $t$Schweinelunge – leichtes, fettarmes Organ. Als Ergänzung des Fleischanteils füttern, getrocknet auch ein beliebter Snack.$t$),
  ('ef60c485-97b6-4285-b971-92663e5dfd57', $t$Schweineschmalz$t$, $t$Schweineschmalz – reines tierisches Fett, konzentrierte Energie. Reines Fett – konzentrierte Energiequelle. Sparsam verwenden, vor allem bei aktiven oder untergewichtigen Hunden.$t$),
  ('b5129d74-6082-416d-a926-d3512ebd7381', $t$Schweineherz$t$, $t$Schweineherz – Muskelorgan mit Taurin. Muskelorgan, reich an Taurin – zählt zum Muskelfleisch, nicht zu den Organen. Bis zu 10–15 % der Ration.$t$),
  ('4746ff20-9eb2-49c5-a856-bf10ed381957', $t$Schweineohren$t$, $t$Schweineohren – knorpeliger Kausnack. Knorpelteil – natürliche Quelle von Glucosamin und Chondroitin für die Gelenke. Beliebter Kausnack.$t$),
  ('b50e8776-88e4-41b9-b0bd-8898b0de24a7', $t$Schweinebries$t$, $t$Schweinebries – drüsiges sekretorisches Organ, milder Geschmack. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('3b5e40a9-b3d2-438d-b49f-bb8bede65120', $t$Schweinebauch$t$, $t$Schweinebauch – sehr fettes, energiereiches Stück. Sparsam. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('6c21434d-854d-405e-831b-54fe8eb33d95', $t$Schweinezunge$t$, $t$Schweinezunge – fettreicheres Muskelfleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus.$t$),
  ('e7b543db-0607-4c85-b4a5-eb47289b8784', $t$Schweinehirn$t$, $t$Schweinehirn – reich an Fetten und DHA. Sekretorisches Organ (Innereien). Macht zusammen mit der Leber ca. 10 % der Ration aus, davon Organe außer Leber ~5 %.$t$),
  ('c3268866-3fc0-45ad-86d3-546ad12c8d3f', $t$Schweineschwanz$t$, $t$Schweineschwanz – fetter essbarer Knochen mit Knorpel. Essbarer weicher Knochen – Kalziumquelle. Macht ca. 10–15 % der Ration aus. IMMER roh, niemals gekocht (gekochte Knochen splittern).$t$),
  ('6e8b6695-b121-4fa1-b17e-9fce79b614d1', $t$Schweinemagen$t$, $t$Schweinemagen – muskulöses Organ, unterstützt die Verdauung. Magen (Pansen) – grün und ungewaschen ist er großartig für Verdauung und Mikrobiom. Zählt zum Muskelfleisch.$t$),
  ('914c4da0-4e64-4384-b334-59fdbf8516db', $t$Hirschfleisch$t$, $t$Hirschfleisch – mageres dunkles Fleisch. Basis der Ration – macht 50–70 % des Fleischanteils aus. Stammt das Wild nicht aus einer geprüften Quelle (z. B. aus dem Supermarkt), lieber durchgaren.$t$)
) as v(food_id, name, description)
where not exists (
  select 1 from public.food_translations t where t.food_id = v.food_id::uuid and t.locale = 'de'
);
